"use strict";

const mongoose = require("mongoose");

// ============================================
// LAX AGENT DEVICE MODEL
// Purpose: Store registered laptop identities
// ============================================

const agentDeviceSchema = new mongoose.Schema(
  {
    // Permanent system ID.
    deviceId: {
      type: String,
      required: true,
      unique: true,
      trim: true,
    },

    // Installation identity generated by Local Agent.
    installationId: {
      type: String,
      required: true,
      unique: true,
      trim: true,
    },

    // Owner of this laptop.
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      required: true,
      index: true,
    },

    // SHA-256 hash of permanent device credential.
    tokenHash: {
      type: String,
      required: true,
      select: false,
    },

    deviceName: {
      type: String,
      required: true,
      trim: true,
    },

    deviceType: {
      type: String,
      enum: ["laptop"],
      default: "laptop",
    },

    os: {
      type: String,
      default: "unknown",
    },

    status: {
      type: String,
      enum: ["active", "inactive"],
      default: "active",
    },

    revoked: {
      type: Boolean,
      default: false,
    },

    lastSeen: {
      type: Date,
      default: null,
    },

    pairedAt: {
      type: Date,
      default: Date.now,
    },
  },
  {
    timestamps: true,
  }
);

module.exports = mongoose.model(
  "AgentDevice",
  agentDeviceSchema
);